INSERT OR REPLACE INTO services (url, name, description, status) VALUES ('https://revistacorrespondenciasyanalisis.edu.pe/', 'Revista Correspondencias y Análisis', 'Correspondencias & Análisis es una revista de comunicación social que publica artículos especializados en comunicación y áreas afines, los cuales son originales e inéditos.', 'up');
INSERT OR REPLACE INTO services (url, name, description, status) VALUES ('https://revistaliberabit.edu.pe/', 'Revista Liberabit', 'Liberabit, es una publicación de la Escuela Profesional de Psicología de la Universidad de San Martín de Porres (Lima, Perú). Inicia sus actividades en 1995 con una periodicidad anual, desde el año 2008 se publica semestralmente (enero-junio; julio-diciembre) y actualmente se publica de manera continua.', 'up');
INSERT OR REPLACE INTO services (url, name, description, status) VALUES ('https://revistaturismoypatrimonio.edu.pe/', 'Revista Turismo y Patrimonio', 'Turismo y Patrimonio es la revista del Instituto de Investigación de la Facultad de Ciencias de la Comunicación, Turismo y Psicología de la Universidad de San Martín de Porres. Es una publicación semestral de ciencias sociales aplicadas y de enfoque multidisciplinario. Su propósito es exponer a la comunidad científica y académica las diversas perspectivas, posturas y resultados sobre temas vinculados al turismo y el patrimonio, a través de artículos de investigación en español e inglés.', 'up');
